import json
import os
import sys

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
SUMMARY_PATH = os.path.join(BASE_DIR, 'summary.json')
EXPECTED = {'rows': 3, 'average': 4}


def main():
    if not os.path.exists(SUMMARY_PATH):
        print('FAIL: summary.json not found')
        return 1
    with open(SUMMARY_PATH, encoding='utf-8') as handle:
        summary = json.load(handle)

    failures = []
    for key, expected in EXPECTED.items():
        actual = summary.get(key)
        if actual != expected:
            failures.append('%s: expected %r, got %r' % (key, expected, actual))
    if set(summary) != set(EXPECTED):
        failures.append('unexpected keys: %s' % sorted(summary))

    if failures:
        for failure in failures:
            print('FAIL: %s' % failure)
        return 1

    print('PASS: summary.json %s' % json.dumps(summary, sort_keys=True))
    return 0


if __name__ == '__main__':
    sys.exit(main())

